from pathlib import Path
p=Path('tools/decode/sim.py');s=p.read_text();s=s.replace('import subprocess','import subprocess\nimport os, sys, re, shlex, hashlib, json')
s=s.replace('TIMEOUT_RC = 124','SIMULATOR = os.environ.get("UTPU_SIM", "icarus")\nif "--sim" in sys.argv:\n    i = sys.argv.index("--sim")\n    SIMULATOR = sys.argv[i+1]\n    del sys.argv[i:i+2]\nif SIMULATOR not in ("icarus", "verilator"):\n    raise ValueError("--sim must be icarus or verilator")\nos.environ["UTPU_SIM"] = SIMULATOR\nVERILATOR_TOOLS = Path(os.environ.get("UTPU_VERILATOR_TOOLS", str(ROOT.parent / "uTPU-research/research/data/tools/usr")))\n\ndef linux_path(path):\n    text = str(Path(path).resolve()).replace(chr(92), "/")\n    return re.sub(r"^([A-Za-z]):", lambda m: "/mnt/"+m[1].lower(), text)\n\ndef simulator_identity():\n    if SIMULATOR == "icarus":\n        exe, compiler = VVP, IVERILOG\n        version = subprocess.run([str(exe), "-V"], capture_output=True, text=True).stderr.strip()\n    else:\n        exe = VERILATOR_TOOLS / "bin/verilator_bin"\n        compiler = exe\n        version = subprocess.run(["wsl", "-d", "Ubuntu", "--", linux_path(exe), "--version"], capture_output=True, text=True).stdout.strip()\n    return {"name": SIMULATOR, "version": version, "executable": str(exe), "executable_sha256": hashlib.sha256(exe.read_bytes()).hexdigest(), "compiler_sha256": hashlib.sha256(compiler.read_bytes()).hexdigest()}\n\ndef run_verilator(sources, top, tb, plusargs, defines, timeout, compile_timeout):\n    tag = Path(tb).stem + ("_"+"_".join(defines) if defines else "")\n    converted = BUILD / (tag+"_verilator.sv")\n    text = Path(tb).read_text()\n    text = re.sub(r"([A-Za-z]):/", lambda m: "/mnt/"+m[1].lower()+"/", text)\n    converted.write_text(text)\n    obj = BUILD / (tag+"_obj")\n    args = [linux_path(VERILATOR_TOOLS/"bin/verilator_bin"), "--binary", "--timing", "-Wno-fatal", "-j", "1", "--top-module", top, "--Mdir", linux_path(obj), *["-D"+x for x in defines], *[linux_path(x) for x in sources], linux_path(converted)]\n    command = "export VERILATOR_ROOT="+shlex.quote(linux_path(VERILATOR_TOOLS/"share/verilator"))+"; "+shlex.join(args)\n    result = subprocess.run(["wsl","-d","Ubuntu","--","bash","-lc",command], cwd=ROOT, capture_output=True,text=True,timeout=compile_timeout)\n    (BUILD/(tag+"_compile.log")).write_text(result.stdout+result.stderr)\n    if result.returncode: raise RuntimeError("Verilator compile failed: "+(result.stdout+result.stderr)[-4000:])\n    try:\n        r = subprocess.run(["wsl","-d","Ubuntu","--",linux_path(obj/("V"+top)),*map(str,plusargs)],cwd=ROOT,capture_output=True,text=True,timeout=timeout)\n        return r.returncode,r.stdout+r.stderr\n    except subprocess.TimeoutExpired as e:\n        return TIMEOUT_RC,_text(e.stdout)+"\\nTIMEOUT Verilator wall cap exceeded\\n"\n\nTIMEOUT_RC = 124')
s=s.replace('    exe = BUILD /', '    if SIMULATOR == "verilator":\n        return run_verilator(sources, top, tb, plusargs, defines, timeout, compile_timeout)\n    exe = BUILD /')
p.write_text(s)
p=Path('tools/decode/provenance.py');s=p.read_text().replace('import glob, hashlib, subprocess','import glob, hashlib, subprocess, sys, platform\nimport numpy as np\nfrom sim import simulator_identity')
s=s.replace('FAULT_SOURCES = [','FAULT_SOURCES = [*NUMERICS, *M260, *M15, *LUTS, ')
s=s.replace("    return res\n", "    res['tool:simulator'] = simulator_identity()\n    res['runtime:python'] = hashlib.sha256(sys.version.encode()).hexdigest()\n    res['runtime:numpy'] = hashlib.sha256(np.__version__.encode()).hexdigest()\n    return res\n")
s=s.replace("    for k, h in prov.items():", "    for k, h in prov.items():\n        if k == 'tool:simulator':\n            import sim\n            selected = sim.SIMULATOR\n            try:\n                sim.SIMULATOR = h['name']\n                if simulator_identity() != h: msgs.append(f'stale {name}: simulator identity changed')\n            except Exception as exc:\n                msgs.append(f'stale {name}: simulator identity unavailable: {exc}')\n            finally: sim.SIMULATOR = selected\n            continue\n        if k.startswith('runtime:'):\n            value = sys.version if k == 'runtime:python' else np.__version__\n            if hashlib.sha256(value.encode()).hexdigest() != h: msgs.append(f'stale {name}: {k} changed')\n            continue")
# Coverage requires new virtual inputs; protects old artifacts from silently passing.
s=s.replace("    return [f'provenance of {name} lacks {f}' for f in need if f not in prov]", "    return [f'provenance of {name} lacks {f}' for f in [*need, 'tool:simulator', 'runtime:python', 'runtime:numpy'] if f not in prov]")
p.write_text(s)
